% =============================================================================
% Church of the Word Podcast Episodes
% Author: rpadgett
%
% These facts are NOT hand-verified content matches like story_reference or
% non_canonical_story_reference. They are a mechanical index: each episode is
% tagged with the book/chapter it discusses (from its own Spotify description),
% and related_teaching/3 (rules/teachings.pl) surfaces any episode whose tag
% overlaps a command's own scripture_reference. Treat matches as "may cover this
% passage," not as a confirmed one-to-one illustration of the command.
%
% To add a new episode (added weekly): append one podcast_episode/3 fact and its
% podcast_episode_reference/2 tags below. No rebuild or restart needed — Prolog
% is reconsulted fresh on every API request.
% =============================================================================

